INSERT INTO FILMS_FILM (title, description, director, release_date, img_Path) VALUES ('Titanic', 'A love story set against the backdrop of the ill-fated maiden voyage of the RMS Titanic.', 'James Cameron', '1997-12-19','https://cdn.europosters.eu/image/1300/posters/pokemon-pikachu-neon-i71936.jpg');
INSERT INTO FILMS_FILM (title, description, director, release_date, img_Path) VALUES ('The Godfather', 'The aging patriarch of an organized crime dynasty transfers control of his clandestine empire to his reluctant son.', 'Francis Ford Coppola', '1972-03-24','pica.jpeg');
