INSERT INTO FILMS_FILM (title, description, director, release_date, img_Path) VALUES ('Forrest Gump', 'The presidencies of Kennedy and Johnson, the Vietnam War, the Watergate scandal and other historical events unfold through the perspective of an Alabama man with an IQ of 75.', 'Robert Zemeckis', '1994-07-06','https://musicart.xboxlive.com/7/40025100-0000-0000-0000-000000000002/504/image.jpg?w=1920&h=1080');
INSERT INTO FILMS_FILM (title, description, director, release_date, img_Path) VALUES ('Inception', 'A thief who steals corporate secrets through the use of dream-sharing technology is given the inverse task of planting an idea into the mind of a CEO.', 'Christopher Nolan', '2010-07-16','https://flhsnavigator.com/wp-content/uploads/2021/10/url-4.jpeg?w=810');
INSERT INTO FILMS_FILM (title, description, director, release_date, img_Path) VALUES ('The Matrix', 'A computer hacker learns from mysterious rebels about the true nature of his reality and his role in the war against its controllers.', 'Lana Wachowski, Lilly Wachowski', '1999-03-31','https://m.media-amazon.com/images/M/MV5BN2NmN2VhMTQtMDNiOS00NDlhLTliMjgtODE2ZTY0ODQyNDRhXkEyXkFqcGc@._V1_.jpg');
INSERT INTO FILMS_FILM (title, description, director, release_date, img_Path) VALUES ('Fight Club', 'An insomniac office worker and a devil-may-care soap maker form an underground fight club that evolves into much more.', 'David Fincher', '1999-10-15','https://image.tmdb.org/t/p/original/eTfuFbfeKVP53AfIYCVomvIN0rC.jpg');
INSERT INTO FILMS_FILM (title, description, director, release_date, img_Path) VALUES ('The Lord of the Rings: The Fellowship of the Ring', 'A hobbit named Frodo Baggins is recruited to join a quest to destroy the One Ring and save Middle-earth from Sauron.', 'Peter Jackson', '2001-12-19','https://upload.wikimedia.org/wikipedia/en/5/53/L.O.R.D_Legend_of_Ravaging_Dynasties_poster.jpeg');
